		int iSlow26 = iSlow2 >= 7;
		int iSlow27 = iSlow2 >= 6;
		int iSlow28 = iSlow2 >= 8;
		float fSlow29 = fConst20 * std::pow(1e+01f, 0.05f * static_cast<float>(fVslider5));
		float fSlow30 = std::pow(1e+01f, 0.05f * ((iSlow3) ? ((iSlow26) ? ((iSlow28) ? 10.5f : 8.9f) : ((iSlow27) ? 7.1f : 5.2f)) : ((iSlow4) ? ((iSlow25) ? 3.0f : 0.4f) : ((iSlow5) ? -2.5f : ((iSlow6) ? -5.4f : -7.5f)))));
